--
-- Table structure for table `dish_suggestions`
--

DROP TABLE IF EXISTS `dish_suggestions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `dish_suggestions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `dish_id` bigint unsigned NOT NULL,
  `suggested_dish_id` bigint unsigned NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `dish_suggestions_dish_id_suggested_dish_id_unique` (`dish_id`,`suggested_dish_id`),
  KEY `dish_suggestions_suggested_dish_id_foreign` (`suggested_dish_id`),
  CONSTRAINT `dish_suggestions_dish_id_foreign` FOREIGN KEY (`dish_id`) REFERENCES `dishes` (`id`) ON DELETE CASCADE,
  CONSTRAINT `dish_suggestions_suggested_dish_id_foreign` FOREIGN KEY (`suggested_dish_id`) REFERENCES `dishes` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1316 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

