--
-- Table structure for table `dishes`
--

DROP TABLE IF EXISTS `dishes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `dishes` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `restaurant_id` bigint unsigned NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name_ar` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `description_ar` text COLLATE utf8mb4_unicode_ci,
  `price` decimal(10,2) NOT NULL,
  `currency` varchar(3) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'USD',
  `calories` int unsigned DEFAULT NULL,
  `category` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `category_ar` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('draft','published') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `item_type` enum('prepared_dish','prepared_drink','packaged_drink','other_product') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'prepared_dish',
  `direct_stock_ingredient_id` bigint unsigned DEFAULT NULL,
  `direct_stock_quantity_per_sale` decimal(12,3) DEFAULT NULL,
  `is_anchor` tinyint(1) NOT NULL DEFAULT '0',
  `is_profitable` tinyint(1) NOT NULL DEFAULT '0',
  `image_url` longtext COLLATE utf8mb4_unicode_ci,
  `brand` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `barcode` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `size_label` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `packaged_unit` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cost_price` decimal(12,2) DEFAULT NULL,
  `supplier` varchar(180) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `packaged_stock_quantity` decimal(12,3) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `dishes_uuid_unique` (`uuid`),
  KEY `dishes_restaurant_id_status_index` (`restaurant_id`,`status`),
  KEY `dishes_restaurant_id_deleted_at_index` (`restaurant_id`,`deleted_at`),
  KEY `dishes_restaurant_is_anchor_index` (`restaurant_id`,`is_anchor`),
  KEY `dishes_restaurant_is_profitable_index` (`restaurant_id`,`is_profitable`),
  KEY `dishes_direct_stock_ingredient_id_foreign` (`direct_stock_ingredient_id`),
  KEY `dishes_restaurant_item_type_index` (`restaurant_id`,`item_type`),
  KEY `dishes_restaurant_item_type_status_index` (`restaurant_id`,`item_type`,`status`),
  KEY `dishes_restaurant_category_status_index` (`restaurant_id`,`category`,`status`),
  KEY `dishes_restaurant_status_deleted_index` (`restaurant_id`,`status`,`deleted_at`),
  CONSTRAINT `dishes_direct_stock_ingredient_id_foreign` FOREIGN KEY (`direct_stock_ingredient_id`) REFERENCES `ingredients` (`id`) ON DELETE SET NULL,
  CONSTRAINT `dishes_restaurant_id_foreign` FOREIGN KEY (`restaurant_id`) REFERENCES `restaurants` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2382 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

