DROP TABLE IF EXISTS `event_menu_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `event_menu_items` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `event_reservation_id` bigint unsigned NOT NULL,
  `dish_id` bigint unsigned NOT NULL,
  `planned_quantity` int unsigned NOT NULL,
  `prep_notes` text COLLATE utf8mb4_unicode_ci,
  `dish_name_snapshot` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `category_snapshot` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
