INSERT INTO `features` VALUES (34,'qr_menu','QR Menu','Guest menu access through QR tables and links.','Menu',0,'2026-05-04 19:39:35','2026-05-04 19:39:35'),(35,'table_ordering','Table Ordering','Guests can place orders directly from table sessions.','Orders',0,'2026-05-04 19:39:35','2026-05-04 19:39:35'),(36,'waiter_call','Waiter Call','Guests can request waiter help from their table.','Service',0,'2026-05-04 19:39:35','2026-05-04 19:39:35'),(37,'request_bill','Request Bill','Guests can request bill assistance digitally.','Service',0,'2026-05-04 19:39:35','2026-05-04 19:39:35'),(38,'inventory','Inventory','Ingredient inventory tracking tools.','Inventory',0,'2026-05-04 19:39:35','2026-05-04 19:39:35'),(39,'ingredient_stock_deduction','Ingredient Stock Deduction','Deduct ingredient stock from confirmed orders.','Inventory',0,'2026-05-04 19:39:35','2026-05-04 19:39:35'),(40,'finance_dashboard','Finance Dashboard','Revenue, invoice, and finance overview dashboard.','Finance',0,'2026-05-04 19:39:35','2026-05-04 19:39:35'),(41,'vat_invoices','VAT Invoices','Issue tax-ready VAT invoices.','Finance',0,'2026-05-04 19:39:35','2026-05-04 19:39:35'),(42,'expense_management','Expense Management','Track and classify operating expenses.','Finance',0,'2026-05-04 19:39:35','2026-05-04 19:39:35'),(43,'payroll_management','Payroll Management','Manage payroll periods, entries, and summaries.','Finance',0,'2026-05-04 19:39:35','2026-05-04 19:39:35'),(44,'dish_profitability','Dish Profitability','Show cost and margin analytics per dish.','Finance',0,'2026-05-04 19:39:35','2026-05-04 19:39:35'),(45,'invoice_splitting','Invoice Splitting','Allow guests and staff to split table invoice totals by order or equally.','Finance',0,'2026-05-04 19:39:35','2026-05-04 19:39:35'),(46,'ai_recommendations','AI Recommendations','AI dish recommendations and alternatives.','AI',0,'2026-05-04 19:39:35','2026-05-04 19:39:35'),(47,'ai_chatbot','AI Chatbot','Conversational guest assistant for menu flows.','