CREATE TABLE `ingredients` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `restaurant_id` bigint unsigned NOT NULL,
  `global_ingredient_id` bigint unsigned DEFAULT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name_ar` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `stock_unit` enum('g','ml','piece') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'piece',
  `current_stock_quantity` decimal(12,3) NOT NULL DEFAULT '0.000',
  `low_stock_threshold` decimal(12,3) NOT NULL DEFAULT '0.000',
  `target_quantity` decimal(12,3) NOT NULL DEFAULT '0.000',
  `unit_cost_cents` bigint DEFAULT NULL,
  `average_cost_cents` bigint DEFAULT NULL,
  `last_cost_cents` bigint DEFAULT NULL,
  `cost_currency` char(3) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `storage_disk` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'public',
  `file_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_file_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `file_size` bigint DEFAULT NULL,
  `mime_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ingredients_restaurant_id_name_unique` (`restaurant_id`,`name`),
  UNIQUE KEY `ingredients_uuid_unique` (`uuid`),
  KEY `ingredients_restaurant_id_created_at_index` (`restaurant_id`,`created_at`),
  KEY `ingredients_restaurant_stock_unit_index` (`restaurant_id`,`stock_unit`),
  KEY `ingredients_restaurant_stock_quantity_index` (`restaurant_id`,`current_stock_quantity`),
  KEY `ingredients_restaurant_is_active_index` (`restaurant_id`,`is_active`),
  KEY `ingredients_global_ingredient_id_foreign` (`global_ingredient_id`),
  KEY `ingredients_restaurant_global_ingredient_index` (`restaurant_id`,`global_ingredient_id`),
  CONSTRAINT `ingredients_global_ingredient_id_foreign` FOREIGN KEY (`global_ingredient_id`) REFERENCES `global_ingredients` (`id`) ON DELETE SET NULL,
  CONSTRAINT `ingredients_restaurant_id_foreign` FOREIGN KEY (`restaurant_id`) REFERENCES `restaurants` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=547 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
