--
-- Table structure for table `order_items`
--

DROP TABLE IF EXISTS `order_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `order_items` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `order_id` bigint unsigned NOT NULL,
  `dish_id` bigint unsigned DEFAULT NULL,
  `dish_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `unit_price` decimal(10,2) NOT NULL,
  `quantity` int unsigned NOT NULL,
  `line_subtotal` decimal(10,2) NOT NULL,
  `status` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'normal',
  `compensation_type` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'none',
  `compensation_reason` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `complaint_category` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `operational_loss_category` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `adjustment_action_type` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `compensation_note` text COLLATE utf8mb4_unicode_ci,
  `approved_by_staff_id` bigint unsigned DEFAULT NULL,
  `approved_by_staff_name` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `approved_by_staff_role` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `approved_at` timestamp NULL DEFAULT NULL,
  `original_unit_price` decimal(10,2) DEFAULT NULL,
  `final_unit_price` decimal(10,2) DEFAULT NULL,
  `partial_discount_percentage` decimal(5,2) DEFAULT NULL,
  `partial_discount_type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `partial_discount_value` decimal(10,2) DEFAULT NULL,
  `is_complimentary` tinyint(1) NOT NULL DEFAULT '0',
  `accounting_bucket` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `customer_satisfaction_rating` tinyint unsigned DEFAULT NULL,
  `evidence_photo_url` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `order_items_order_id_foreign` (`order_id`),
  KEY `order_items_dish_id_foreign` (`dish_id`),
  KEY `order_items_approved_by_staff_id_foreign` (`approved_by_staff_id`),
  CONSTRAINT `order_items_approved_by_staff_id_foreign` FOREIGN KEY (`approved_by_staff_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `order_items_dish_id_foreign` FOREIGN KEY (`dish_id`) REFERENCES `dishes` (`id`) ON DELETE SET NULL,
  CONSTRAINT `order_items_order_id_foreign` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3213 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

