--
-- Table structure for table `stock_movements`
--

DROP TABLE IF EXISTS `stock_movements`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `stock_movements` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `restaurant_id` bigint unsigned NOT NULL,
  `ingredient_id` bigint unsigned DEFAULT NULL,
  `order_id` bigint unsigned DEFAULT NULL,
  `order_item_id` bigint unsigned DEFAULT NULL,
  `dish_id` bigint unsigned DEFAULT NULL,
  `linked_expense_id` bigint unsigned DEFAULT NULL,
  `performed_by` bigint unsigned DEFAULT NULL,
  `movement_type` enum('opening_balance','restock','manual_adjustment','order_consumption','order_restoration') COLLATE utf8mb4_unicode_ci NOT NULL,
  `inventory_source` enum('recipe_ingredient_usage','direct_packaged_sale') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `unit` enum('g','ml','piece') COLLATE utf8mb4_unicode_ci NOT NULL,
  `quantity_delta` decimal(12,3) NOT NULL,
  `quantity_before` decimal(12,3) DEFAULT NULL,
  `quantity_after` decimal(12,3) DEFAULT NULL,
  `unit_cost_cents` bigint DEFAULT NULL,
  `total_cost_cents` bigint DEFAULT NULL,
  `ingredient_name_snapshot` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `reference` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `occurred_at` timestamp NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `stock_movements_performed_by_foreign` (`performed_by`),
  KEY `stock_movements_ingredient_id_occurred_at_index` (`ingredient_id`,`occurred_at`),
  KEY `stock_movements_restaurant_id_occurred_at_index` (`restaurant_id`,`occurred_at`),
  KEY `stock_movements_order_id_movement_type_index` (`order_id`,`movement_type`),
  KEY `stock_movements_order_item_id_movement_type_index` (`order_item_id`,`movement_type`),
  KEY `stock_movements_linked_expense_id_foreign` (`linked_expense_id`),
  KEY `stock_moves_rest_type_expense_idx` (`restaurant_id`,`movement_type`,`linked_expense_id`),
  KEY `stock_movements_dish_type_index` (`dish_id`,`movement_type`),
  KEY `stock_movements_restaurant_source_index` (`restaurant_id`,`inventory_source`),
  CONSTRAINT `stock_movements_dish_id_foreign` FOREIGN KEY (`dish_id`) REFERENCES `dishes` (`id`) ON DELETE SET NULL,
  CONSTRAINT `stock_movements_ingredient_id_foreign` FOREIGN KEY (`ingredient_id`) REFERENCES `ingredients` (`id`) ON DELETE SET NULL,
  CONSTRAINT `stock_movements_linked_expense_id_foreign` FOREIGN KEY (`linked_expense_id`) REFERENCES `expenses` (`id`) ON DELETE SET NULL,
  CONSTRAINT `stock_movements_order_id_foreign` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE SET NULL,
  CONSTRAINT `stock_movements_order_item_id_foreign` FOREIGN KEY (`order_item_id`) REFERENCES `order_items` (`id`) ON DELETE SET NULL,
  CONSTRAINT `stock_movements_performed_by_foreign` FOREIGN KEY (`performed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `stock_movements_restaurant_id_foreign` FOREIGN KEY (`restaurant_id`) REFERENCES `restaurants` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=278 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

