DROP TABLE IF EXISTS `table_sessions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `table_sessions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `restaurant_id` bigint unsigned NOT NULL,
  `restaurant_table_id` bigint unsigned NOT NULL,
  `table_number` int unsigned NOT NULL,
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `pin_hash` text COLLATE utf8mb4_unicode_ci,
  `pin_attempts` smallint unsigned NOT NULL DEFAULT '0',
  `pin_locked_until` timestamp NULL DEFAULT NULL,
  `opened_at` timestamp NULL DEFAULT NULL,
  `last_activity_at` timestamp NULL DEFAULT NULL,
  `expires_at` timestamp NULL DEFAULT NULL,
  `closed_at` timestamp NULL DEFAULT NULL,
  `close_reason` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `invoice_split_mode` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'none',
  `invoice_split_count` smallint unsigned DEFAULT NULL,
  `invoice_split_allocations` json DEFAULT NULL,
  `created_by_staff_id` bigint unsigned DEFAULT NULL,
  `finalized_by_staff_id` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `table_sessions_uuid_unique` (`uuid`),
  KEY `table_sessions_created_by_staff_id_foreign` (`created_by_staff_id`),
  KEY `table_sessions_finalized_by_staff_id_foreign` (`finalized_by_staff_id`),
  KEY `table_sessions_restaurant_id_table_number_index` (`restaurant_id`,`table_number`),
  KEY `table_sessions_status_expires_at_index` (`status`,`expires_at`),
  KEY `table_sessions_restaurant_table_id_status_index` (`restaurant_table_id`,`status`),
  CONSTRAINT `table_sessions_created_by_staff_id_foreign` FOREIGN KEY (`created_by_staff_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `table_sessions_finalized_by_staff_id_foreign` FOREIGN KEY (`finalized_by_staff_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `table_sessions_restaurant_id_foreign` FOREIGN KEY (`restaurant_id`) REFERENCES `restaurants` (`id`) ON DELETE CASCADE,
  CONSTRAINT `table_sessions_restaurant_table_id_foreign` FOREIGN KEY (`restaurant_table_id`) REFERENCES `restaurant_tables` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=49 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

