  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `table_waves_uuid_unique` (`uuid`),
  KEY `table_waves_resolved_by_foreign` (`resolved_by`),
  KEY `table_waves_restaurant_id_status_index` (`restaurant_id`,`status`),
